style.css:
@-moz-document domain("roblox.com") {
/* Topbar com as cores do Invencível */
    .header-2018, .navigation .rbx-header {
        background-color: #1a4fa0 !important;
        border-bottom: 4px solid #f6cc16 !important;
    }
    
    /* Fundo corrigido e centralizado */
    body, .dark-theme, .light-theme, #container-main, .main-layout {
        background: #0d1b2a url('https://alphacoders.com') no-repeat center center fixed !important;
        background-size: cover !important;
    }
    
    /* Remove fundos pretos que cobrem a imagem */
    .content, #main-body, .wrap {
        background: transparent !important;
    }
    
    /* Caixas de conteúdo semi-transparentes */
    .section-content, .container-main, .profile-header, .game-card, .server-list-container {
        background: rgba(13, 27, 42, 0.85) !important;
        border-radius: 8px !important;
        border: 1px solid #f6cc16 !important;
    }
    
    /* Textos principais e links */
    h1, h2, h3, .text-title, .text-name, .text-description {
        color: #ffffff !important;
    }
    
    a, .text-link {
        color: #f6cc16 !important;
    }
    
    /* Botões */
    .btn-common-play-large, .btn-to-robux, .btn-full-width {
        background-color: #e63946 !important;
        border: none !important;
    }
}
